CREATE FUNCTION public.validate_pdv_sellers() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE previous_order jsonb; next_order jsonb; BEGIN IF auth.uid() IS NULL OR public.has_role(auth.uid(),'admin') THEN RETURN NEW; END IF; FOR previous_order IN SELECT value FROM jsonb_array_elements(OLD.data->'orders') LOOP SELECT value INTO next_order FROM jsonb_array_elements(NEW.data->'orders') WHERE value->>'id'=previous_order->>'id'; IF next_order IS NULL OR next_order->'sellerId' IS DISTINCT FROM previous_order->'sellerId' OR next_order->'sellerName' IS DISTINCT FROM previous_order->'sellerName' THEN RAISE EXCEPTION 'O atendente da venda não pode ser alterado'; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER pdv_seller_integrity BEFORE UPDATE ON public.pdv_state FOR EACH ROW EXECUTE FUNCTION public.validate_pdv_sellers();
CREATE FUNCTION public.revoke_pdv_access(target uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') OR target=auth.uid() THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF EXISTS(SELECT 1 FROM auth.users WHERE id=target AND lower(email)='ultraconnectsaborebrasa@gmail.com') THEN RAISE EXCEPTION 'Não é possível bloquear o administrador principal'; END IF; DELETE FROM public.user_roles WHERE user_id=target; END $$;
REVOKE ALL ON FUNCTION public.revoke_pdv_access(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.revoke_pdv_access(uuid) TO authenticated;